public class InnerClusterClusterInstanceGroupFactory(Action<Humidifier.SageMaker.ClusterTypes.ClusterInstanceGroup> factoryAction = null) : SubResourceFactory<Humidifier.SageMaker.ClusterTypes.ClusterInstanceGroup>
{

    internal InnerClusterClusterSlurmConfigFactory SlurmConfigFactory { get; set; }

    internal InnerClusterClusterCapacityRequirementsFactory CapacityRequirementsFactory { get; set; }

    internal InnerClusterClusterKubernetesConfigFactory KubernetesConfigFactory { get; set; }

    internal InnerClusterClusterNetworkInterfaceFactory NetworkInterfaceFactory { get; set; }

    internal InnerClusterClusterLifeCycleConfigFactory LifeCycleConfigFactory { get; set; }

    internal InnerClusterVpcConfigFactory OverrideVpcConfigFactory { get; set; }

    internal InnerClusterScheduledUpdateConfigFactory ScheduledUpdateConfigFactory { get; set; }

    internal InnerClusterInstanceRequirementsFactory InstanceRequirementsFactory { get; set; }

    internal InnerClusterAutoPatchConfigFactory AutoPatchConfigFactory { get; set; }

    protected override Humidifier.SageMaker.ClusterTypes.ClusterInstanceGroup Create()
    {
        var clusterInstanceGroupResult = CreateClusterInstanceGroup();
        factoryAction?.Invoke(clusterInstanceGroupResult);

        return clusterInstanceGroupResult;
    }

    private Humidifier.SageMaker.ClusterTypes.ClusterInstanceGroup CreateClusterInstanceGroup()
    {
        var clusterInstanceGroupResult = new Humidifier.SageMaker.ClusterTypes.ClusterInstanceGroup();

        return clusterInstanceGroupResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.ClusterTypes.ClusterInstanceGroup result)
    {
        base.CreateChildren(result);

        result.SlurmConfig ??= SlurmConfigFactory?.Build();
        result.CapacityRequirements ??= CapacityRequirementsFactory?.Build();
        result.KubernetesConfig ??= KubernetesConfigFactory?.Build();
        result.NetworkInterface ??= NetworkInterfaceFactory?.Build();
        result.LifeCycleConfig ??= LifeCycleConfigFactory?.Build();
        result.OverrideVpcConfig ??= OverrideVpcConfigFactory?.Build();
        result.ScheduledUpdateConfig ??= ScheduledUpdateConfigFactory?.Build();
        result.InstanceRequirements ??= InstanceRequirementsFactory?.Build();
        result.AutoPatchConfig ??= AutoPatchConfigFactory?.Build();
    }

} // End Of Class

